=== Config.java
     1	package br.com.marealta.pousada;
     2	
     3	import java.time.LocalTime;
     4	import java.time.ZoneId;
     5	import java.util.Map;
     6	
     7	/**
     8	 * Configuração da instalação, lida das variáveis de ambiente.
     9	 *
    10	 * <pre>
    11	 * HOTEL_TEST_MODE=true                  modo de teste
    12	 * HOTEL_ARCHIVE_COPY=NON_TEST_ONLY      cópia para o arquivo (ALWAYS | TEST_ONLY | NON_TEST_ONLY | NEVER)
    13	 * HOTEL_QUIET_HOURS=22:00-07:00         não envia mensagens nesse intervalo (desligado se ausente)
    14	 * HOTEL_QUIET_HOURS_SCOPE=ALWAYS        onde a regra vale
    15	 * HOTEL_DAILY_LIMIT=5                   máximo de mensagens por hóspede por dia (desligado se ausente)
    16	 * HOTEL_DAILY_LIMIT_SCOPE=ALWAYS        onde a regra vale
    17	 * HOTEL_TIMEZONE=America/Sao_Paulo      fuso usado por "madrugada" e "por dia"
    18	 * </pre>
    19	 */
    20	public record Config(boolean testMode, Scope archiveCopy, QuietHours quietHours, Scope quietHoursScope,
    21	                     Integer dailyLimit, Scope dailyLimitScope, ZoneId zone) {
    22	
    23	    /** Onde uma regra vale. */
    24	    public enum Scope {
    25	        ALWAYS, TEST_ONLY, NON_TEST_ONLY, NEVER;
    26	
    27	        public boolean appliesIn(boolean testMode) {
    28	            return switch (this) {
    29	                case ALWAYS -> true;
    30	                case TEST_ONLY -> testMode;
    31	                case NON_TEST_ONLY -> !testMode;
    32	                case NEVER -> false;
    33	            };
    34	        }
    35	    }
    36	
    37	    /** Intervalo [start, end) que pode atravessar a meia-noite. */
    38	    public record QuietHours(LocalTime start, LocalTime end) {
    39	        public boolean contains(LocalTime t) {
    40	            if (start.equals(end)) return false;
    41	            return start.isBefore(end)
    42	                    ? !t.isBefore(start) && t.isBefore(end)
    43	                    : !t.isBefore(start) || t.isBefore(end);
    44	        }
    45	
    46	        static QuietHours parse(String s) {
    47	            String[] p = s.trim().split("-");
    48	            if (p.length != 2) throw new IllegalArgumentException("HOTEL_QUIET_HOURS inválido: " + s);
    49	            return new QuietHours(LocalTime.parse(p[0].trim()), LocalTime.parse(p[1].trim()));
    50	        }
    51	    }
    52	
    53	    public static Config defaults(boolean testMode) {
    54	        return fromEnv(Map.of("HOTEL_TEST_MODE", String.valueOf(testMode)));
    55	    }
    56	
    57	    public static Config fromEnv(Map<String, String> env) {
    58	        boolean test = "true".equalsIgnoreCase(blankToNull(env.get("HOTEL_TEST_MODE")));
    59	        String qh = blankToNull(env.get("HOTEL_QUIET_HOURS"));
    60	        String dl = blankToNull(env.get("HOTEL_DAILY_LIMIT"));
    61	        String tz = blankToNull(env.get("HOTEL_TIMEZONE"));
    62	        return new Config(
    63	                test,
    64	                scope(env.get("HOTEL_ARCHIVE_COPY"), Scope.NON_TEST_ONLY),
    65	                qh == null ? null : QuietHours.parse(qh),
    66	                scope(env.get("HOTEL_QUIET_HOURS_SCOPE"), Scope.ALWAYS),
    67	                dl == null ? null : Integer.valueOf(dl.trim()),
    68	                scope(env.get("HOTEL_DAILY_LIMIT_SCOPE"), Scope.ALWAYS),
    69	                ZoneId.of(tz == null ? "America/Sao_Paulo" : tz));
    70	    }
    71	
    72	    private static Scope scope(String v, Scope def) {
    73	        v = blankToNull(v);
    74	        return v == null ? def : Scope.valueOf(v.trim().toUpperCase());
    75	    }
    76	
    77	    private static String blankToNull(String s) {
    78	        return s == null || s.isBlank() ? null : s;
    79	    }
    80	}
