=== Pricing.java
     1	package br.com.marealta.pousada;
     2	
     3	import br.com.marealta.pousada.Domain.RatePlan;
     4	
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.LocalDate;
     8	
     9	/** Cálculo de diárias, desconto e total. Todo passo é arredondado a centavos (meio para o par). */
    10	public final class Pricing {
    11	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    13	
    14	    private Pricing() {}
    15	
    16	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    17	
    18	    public static BigDecimal money(BigDecimal v) {
    19	        return v.setScale(2, RoundingMode.HALF_EVEN);
    20	    }
    21	
    22	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    23	    public static boolean isHighSeason(LocalDate night) {
    24	        int m = night.getMonthValue();
    25	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
    26	    }
    27	
    28	    public static BigDecimal nightPrice(BigDecimal nightlyRate, LocalDate night) {
    29	        BigDecimal base = money(nightlyRate);
    30	        return isHighSeason(night) ? money(base.multiply(HIGH_SEASON_FACTOR)) : base;
    31	    }
    32	
    33	    public static Quote quote(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    34	        BigDecimal subtotal = money(BigDecimal.ZERO);
    35	        int nights = 0;
    36	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    37	            subtotal = money(subtotal.add(nightPrice(nightlyRate, d)));
    38	            nights++;
    39	        }
    40	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    41	                ? money(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    42	                : money(BigDecimal.ZERO);
    43	        return new Quote(nights, subtotal, discount, money(subtotal.subtract(discount)));
    44	    }
    45	}
=== Receipt.java
     1	package br.com.marealta.pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.text.DecimalFormat;
     5	import java.text.DecimalFormatSymbols;
     6	import java.time.LocalDate;
     7	import java.time.format.DateTimeFormatter;
     8	import java.util.Locale;
     9	
    10	/** Comprovante de reserva: dados e texto. */
    11	public record Receipt(long reservationId, String guestName, String guestCpf, int roomNumber, String roomType,
    12	                      LocalDate checkIn, LocalDate checkOut, int nights, BigDecimal subtotal,
    13	                      BigDecimal discount, BigDecimal total) {
    14	
    15	    public static final String TITLE = "Comprovante de reserva";
    16	    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    17	
    18	    public static String brl(BigDecimal v) {
    19	        DecimalFormatSymbols s = new DecimalFormatSymbols(Locale.ROOT);
    20	        s.setDecimalSeparator(',');
    21	        s.setGroupingSeparator('.');
    22	        return "R$ " + new DecimalFormat("#,##0.00", s).format(v);
    23	    }
    24	
    25	    private static String cpf(String raw) {
    26	        if (raw.matches("\\d{11}")) {
    27	            return raw.substring(0, 3) + "." + raw.substring(3, 6) + "." + raw.substring(6, 9) + "-" + raw.substring(9);
    28	        }
    29	        return raw;
    30	    }
    31	
    32	    public String text() {
    33	        StringBuilder sb = new StringBuilder();
    34	        sb.append(TITLE).append(" nº ").append(reservationId).append('\n');
    35	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(cpf(guestCpf)).append(")\n");
    36	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    37	        sb.append("Entrada: ").append(BR_DATE.format(checkIn)).append(" | Saída: ").append(BR_DATE.format(checkOut))
    38	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    39	        sb.append("Diárias: ").append(brl(subtotal)).append('\n');
    40	        if (discount.signum() > 0) {
    41	            sb.append("Desconto: ").append(brl(discount)).append('\n');
    42	        }
    43	        sb.append("Total: ").append(brl(total));
    44	        return sb.toString();
    45	    }
    46	
    47	    public String confirmationEmailBody() {
    48	        return "Olá, " + guestName + "!\n\n"
    49	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    50	                + text() + "\n\n"
    51	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    52	                + "Até breve!";
    53	    }
    54	
    55	    public static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    56	}

