    10	import java.util.List;
    11	
    12	/**
    13	 * Aplica as regras de envio a cada mensagem e registra o resultado.
    14	 *
    15	 * Fluxo: (1) regras de bloqueio; se alguma bloqueia, a mensagem fica BLOCKED com o endereço original e
    16	 * nada mais acontece; (2) regras de expansão (cópia para o arquivo); (3) regras de transformação
    17	 * (redirecionamento do modo de teste), aplicadas a todas as mensagens que vão sair, inclusive cópias.
    18	 * As regras que valem são escolhidas pela configuração da instalação.
    19	 */
    20	public class MessageDispatcher {
    21	    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    22	    public static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";
    23	
    24	    /** Mensagem ainda sem id. */
    25	    public record Draft(String channel, String to, String subject, String body) {}
    26	
    27	    /** Onde as mensagens são guardadas. */
    28	    public interface Store {
    29	        /** Guarda e devolve a mensagem com id. guestKey identifica o hóspede (null para cópias). */
    30	        Message save(Draft draft, MessageStatus status, String guestKey);
    31	
    32	        int countSent(String guestKey, Instant from, Instant to);
    33	    }
    34	
    35	    interface BlockRule { boolean blocks(Draft d, String guestKey, Store store); }
    36	    interface ExpandRule { List<Draft> extra(Draft d); }
    37	    interface TransformRule { Draft apply(Draft d); }
    38	
    39	    private final Config config;
    40	    private final Clock clock;
    41	    private final List<BlockRule> blockRules = new ArrayList<>();
    42	    private final List<ExpandRule> expandRules = new ArrayList<>();
    43	    private final List<TransformRule> transformRules = new ArrayList<>();
    44	
    45	    public MessageDispatcher(Config config, Clock clock) {
    46	        this.config = config;
    47	        this.clock = clock;
    48	        boolean test = config.testMode();
    49	
    50	        blockRules.add((d, key, store) -> !isValidAddress(d.to()));
    51	        if (config.quietHours() != null && config.quietHoursScope().appliesIn(test)) {
    52	            blockRules.add((d, key, store) ->
    53	                    config.quietHours().contains(ZonedDateTime.now(clock.withZone(config.zone())).toLocalTime()));
    54	        }
    55	        if (config.dailyLimit() != null && config.dailyLimitScope().appliesIn(test)) {
    56	            blockRules.add((d, key, store) -> {
    57	                ZonedDateTime now = ZonedDateTime.now(clock.withZone(config.zone()));
    58	                Instant start = now.toLocalDate().atStartOfDay(config.zone()).toInstant();
    59	                Instant end = now.toLocalDate().plusDays(1).atStartOfDay(config.zone()).toInstant();
    60	                return store.countSent(key, start, end) >= config.dailyLimit();
    61	            });
    62	        }
    63	        if (config.archiveCopy().appliesIn(test)) {
    64	            expandRules.add(d -> List.of(new Draft(d.channel(), ARCHIVE_ADDRESS, "[Cópia] " + d.subject(), d.body())));
    65	        }
    66	        if (test) {
    67	            // Sempre vale no modo de teste: não é configurável, para nada sair para endereço real.
    68	            transformRules.add(d -> new Draft(d.channel(), TEST_ADDRESS, "[TESTE] " + d.subject(),
    69	                    "Destinatário original: " + d.to() + "\n" + d.body()));
    70	        }
    71	    }
    72	
    73	    /** Um único @, algo antes dele e, depois, um nome com pelo menos um ponto no meio. */
    74	    public static boolean isValidAddress(String address) {
    75	        if (address == null || address.chars().anyMatch(Character::isWhitespace)) return false;
    76	        int at = address.indexOf('@');
    77	        if (at <= 0 || at != address.lastIndexOf('@')) return false;
    78	        String domain = address.substring(at + 1);
    79	        return domain.length() > 2 && domain.substring(1, domain.length() - 1).contains(".");
    80	    }
    81	
    82	    public List<Message> dispatch(Store store, Draft original) {
    83	        String guestKey = original.to() == null ? "" : original.to().trim().toLowerCase();
    84	        for (BlockRule r : blockRules) {
    85	            if (r.blocks(original, guestKey, store)) {
    86	                return List.of(store.save(original, MessageStatus.BLOCKED, guestKey));
    87	            }
    88	        }
    89	        List<Draft> out = new ArrayList<>();
    90	        out.add(original);
    91	        for (ExpandRule r : expandRules) out.addAll(r.extra(original));
    92	
    93	        List<Message> saved = new ArrayList<>();
    94	        for (int i = 0; i < out.size(); i++) {
    95	            Draft d = out.get(i);
    96	            for (TransformRule t : transformRules) d = t.apply(d);
    97	            saved.add(store.save(d, MessageStatus.SENT, i == 0 ? guestKey : null));
    98	        }
    99	        return saved;
   100	    }
   101	}
