    27	    public <T> T tx(Work<T> work) {
    28	        try (Connection c = ds.getConnection()) {
    29	            c.setAutoCommit(false);
    30	            try {
    31	                T result = work.run(c);
    32	                c.commit();
    33	                return result;
    34	            } catch (Throwable t) {
    35	                c.rollback();
    36	                throw t;
    37	            }
    38	        } catch (SQLException e) {
    39	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
    40	        }
    41	    }
