    27	    public <T> T tx(Work<T> work) {
    28	        try (Connection c = ds.getConnection()) {
    29	            c.setAutoCommit(false);
    30	            try {
    31	                T result = work.run(c);
    32	                c.commit();
    33	                return result;
    34	            } catch (Throwable t) {
    35	                c.rollback();
    36	                throw t;
    37	            }
    38	        } catch (SQLException e) {
    39	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
    40	        }
    41	    }
    42	
    43	    /** Cria o que falta no banco (tabelas e os cinco quartos). Seguro com várias instâncias subindo juntas. */
    44	    public void migrate() {
    45	        try (Connection c = ds.getConnection()) {
    46	            c.setAutoCommit(true);
    47	            try (Statement s = c.createStatement()) {
    48	                s.execute("SELECT pg_advisory_lock(727001)");
    49	                try {
    50	                    s.execute("""
    51	                            CREATE TABLE IF NOT EXISTS rooms (
    52	                              number INT PRIMARY KEY,
    53	                              type TEXT NOT NULL,
    54	                              capacity INT NOT NULL,
    55	                              nightly_rate NUMERIC(12,2) NOT NULL)""");
    56	                    s.execute("""
    57	                            CREATE TABLE IF NOT EXISTS reservations (
    58	                              id BIGSERIAL PRIMARY KEY,
    59	                              room_number INT NOT NULL REFERENCES rooms(number),
    60	                              guest_name TEXT NOT NULL,
    61	                              guest_email TEXT NOT NULL,
    62	                              guest_cpf TEXT NOT NULL,
    63	                              check_in DATE NOT NULL,
    64	                              check_out DATE NOT NULL,
    65	                              guests INT NOT NULL,
    66	                              rate_plan TEXT NOT NULL,
    67	                              nights INT NOT NULL,
    68	                              subtotal NUMERIC(12,2) NOT NULL,
    69	                              discount NUMERIC(12,2) NOT NULL,
    70	                              total NUMERIC(12,2) NOT NULL,
    71	                              status TEXT NOT NULL,
    72	                              amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,
    73	                              refund NUMERIC(12,2),
    74	                              CHECK (check_out > check_in))""");
    75	                    s.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations(room_number, check_in, check_out)");
    76	                    s.execute("CREATE INDEX IF NOT EXISTS reservations_check_in_idx ON reservations(check_in)");
    77	                    s.execute("""
    78	                            CREATE TABLE IF NOT EXISTS messages (
    79	                              id BIGSERIAL PRIMARY KEY,
    80	                              channel TEXT NOT NULL,
    81	                              recipient TEXT NOT NULL,
    82	                              subject TEXT NOT NULL,
    83	                              body TEXT NOT NULL,
    84	                              status TEXT NOT NULL,
    85	                              guest_key TEXT,
    86	                              created_at TIMESTAMPTZ NOT NULL DEFAULT now())""");
    87	                    s.execute("CREATE INDEX IF NOT EXISTS messages_guest_idx ON messages(guest_key, created_at)");
    88	                    s.execute("""
    89	                            INSERT INTO rooms(number, type, capacity, nightly_rate) VALUES
    90	                              (101, 'STANDARD', 2, 249.90),
    91	                              (102, 'STANDARD', 2, 249.90),
    92	                              (201, 'DELUXE', 3, 389.90),
    93	                              (202, 'DELUXE', 3, 389.90),
    94	                              (301, 'SUITE', 4, 579.90)
    95	                            ON CONFLICT (number) DO NOTHING""");
    96	                } finally {
    97	                    s.execute("SELECT pg_advisory_unlock(727001)");
    98	                }
    99	            }
   100	        } catch (SQLException e) {
   101	            throw new IllegalStateException("Falha ao preparar o banco: " + e.getMessage(), e);
   102	        }
   103	    }
   104	
