    62	    public Reservation create(NewReservation n) {
    63	        return db.tx(c -> {
    64	            // Trava o quarto: reservas concorrentes do mesmo quarto são atendidas uma por vez.
    65	            Room room = lockRoom(c, n.roomNumber());
    66	            if (n.guests() > room.capacity()) {
    67	                throw new ApiException(422, "CAPACITY_EXCEEDED",
    68	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes.");
    69	            }
    70	            try (PreparedStatement ps = c.prepareStatement(
    71	                    "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    72	                            + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    73	                ps.setInt(1, room.number());
    74	                ps.setDate(2, Date.valueOf(n.checkOut()));
    75	                ps.setDate(3, Date.valueOf(n.checkIn()));
