    83	            Pricing.Quote q = Pricing.quote(room.nightlyRate(), n.checkIn(), n.checkOut(), n.ratePlan());
    84	            try (PreparedStatement ps = c.prepareStatement(
    85	                    "INSERT INTO reservations(room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, "
    86	                            + "rate_plan, nights, subtotal, discount, total, status, amount_paid) "
    87	                            + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'PENDING',0) RETURNING id")) {
    88	                ps.setInt(1, room.number());
    89	                ps.setString(2, n.guestName());
    90	                ps.setString(3, n.guestEmail());
    91	                ps.setString(4, n.guestCpf());
    92	                ps.setDate(5, Date.valueOf(n.checkIn()));
    93	                ps.setDate(6, Date.valueOf(n.checkOut()));
    94	                ps.setInt(7, n.guests());
    95	                ps.setString(8, n.ratePlan().name());
    96	                ps.setInt(9, q.nights());
    97	                ps.setBigDecimal(10, q.subtotal());
    98	                ps.setBigDecimal(11, q.discount());
    99	                ps.setBigDecimal(12, q.total());
   100	                try (ResultSet rs = ps.executeQuery()) {
   101	                    rs.next();
   102	                    return load(c, rs.getLong(1), false);
   103	                }
   104	            }
   105	        });
   106	    }
   107	
   108	    public Reservation confirm(long id) {
   109	        return db.tx(c -> {
   110	            Reservation r = load(c, id, true);
   111	            requireStatus(r, "confirmar", Status.PENDING);
   112	            update(c, id, "status = 'CONFIRMED', amount_paid = total");
   113	            Reservation confirmed = load(c, id, false);
   114	            Receipt receipt = receipt(c, confirmed);
   115	            dispatcher.dispatch(new JdbcMessageStore(c), new MessageDispatcher.Draft(
   116	                    "EMAIL", confirmed.guestEmail(), Receipt.CONFIRMATION_SUBJECT, receipt.confirmationEmailBody()));
   117	            return confirmed;
   118	        });
   119	    }
   120	
   121	    public Reservation checkIn(long id) {
   122	        return db.tx(c -> {
   123	            requireStatus(load(c, id, true), "fazer check-in de", Status.CONFIRMED);
   124	            update(c, id, "status = 'CHECKED_IN'");
   125	            return load(c, id, false);
   126	        });
   127	    }
   128	
   129	    public Receipt checkOut(long id) {
   130	        return db.tx(c -> {
   131	            requireStatus(load(c, id, true), "fazer check-out de", Status.CHECKED_IN);
   132	            update(c, id, "status = 'CHECKED_OUT'");
   133	            return receipt(c, load(c, id, false));
   134	        });
   135	    }
   136	
   137	    public Reservation cancel(long id) {
   138	        return db.tx(c -> {
   139	            Reservation r = load(c, id, true);
   140	            requireStatus(r, "cancelar", Status.PENDING, Status.CONFIRMED);
   141	            // Reembolso integral só no plano normal; reserva pendente não tem nada pago (amount_paid = 0).
   142	            String refund = r.ratePlan() == RatePlan.STANDARD ? "amount_paid" : "0";
   143	            update(c, id, "status = 'CANCELLED', refund = " + refund);
   144	            return load(c, id, false);
   145	        });
   146	    }
