   148	    // ---------- relatórios ----------
   149	
   150	    public String occupancyCsv(LocalDate date) {
   151	        return db.tx(c -> {
   152	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
   153	            int occupied = 0;
   154	            try (PreparedStatement ps = c.prepareStatement(
   155	                    "SELECT r.room_number, rm.type, r.id, r.check_in, r.check_out FROM reservations r "
   156	                            + "JOIN rooms rm ON rm.number = r.room_number "
   157	                            + "WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND r.check_in <= ? AND r.check_out > ? "
   158	                            + "ORDER BY r.room_number, r.id")) {
   159	                ps.setDate(1, Date.valueOf(date));
   160	                ps.setDate(2, Date.valueOf(date));
   161	                try (ResultSet rs = ps.executeQuery()) {
   162	                    while (rs.next()) {
   163	                        occupied++;
   164	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',').append(rs.getLong(3))
   165	                                .append(',').append(rs.getDate(4).toLocalDate()).append(',')
   166	                                .append(rs.getDate(5).toLocalDate()).append('\n');
   167	                    }
   168	                }
   169	            }
   170	            int total;
   171	            try (PreparedStatement ps = c.prepareStatement("SELECT count(*) FROM rooms");
   172	                 ResultSet rs = ps.executeQuery()) {
   173	                rs.next();
   174	                total = rs.getInt(1);
   175	            }
   176	            return sb.append("total,").append(occupied).append('/').append(total).append('\n').toString();
   177	        });
   178	    }
   179	
   180	    public String revenueCsv(YearMonth month) {
   181	        return db.tx(c -> {
   182	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   183	            BigDecimal sum = Pricing.money(BigDecimal.ZERO);
   184	            try (PreparedStatement ps = c.prepareStatement(
   185	                    "SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0) AS amount "
   186	                            + "FROM reservations WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0 "
   187	                            + "ORDER BY check_in, id")) {
   188	                ps.setDate(1, Date.valueOf(month.atDay(1)));
   189	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
   190	                try (ResultSet rs = ps.executeQuery()) {
   191	                    while (rs.next()) {
   192	                        BigDecimal amount = rs.getBigDecimal(6);
   193	                        sum = sum.add(amount);
   194	                        sb.append(rs.getLong(1)).append(',').append(rs.getInt(2)).append(',')
   195	                                .append(rs.getDate(3).toLocalDate()).append(',').append(rs.getDate(4).toLocalDate())
   196	                                .append(',').append(rs.getString(5)).append(',').append(amount.toPlainString()).append('\n');
   197	                    }
   198	                }
   199	            }
   200	            return sb.append("total,").append(sum.toPlainString()).append('\n').toString();
   201	        });
   202	    }
