   206	    private static void requireStatus(Reservation r, String action, Status... allowed) {
   207	        for (Status s : allowed) if (r.status() == s) return;
   208	        throw ApiException.notAllowed("Não é possível " + action + " uma reserva com situação " + r.status() + ".");
   209	    }
