   211	    private static Room room(ResultSet rs) throws SQLException {
   212	        return new Room(rs.getInt(1), rs.getString(2), rs.getInt(3), rs.getBigDecimal(4));
   213	    }
   214	
   215	    private static Room lockRoom(Connection c, int number) throws SQLException {
   216	        try (PreparedStatement ps = c.prepareStatement(
   217	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ? FOR UPDATE")) {
   218	            ps.setInt(1, number);
   219	            try (ResultSet rs = ps.executeQuery()) {
   220	                if (!rs.next()) throw new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + number + " não existe.");
   221	                return room(rs);
   222	            }
   223	        }
   224	    }
