   226	    private static Reservation load(Connection c, long id, boolean forUpdate) throws SQLException {
   227	        try (PreparedStatement ps = c.prepareStatement(
   228	                "SELECT " + RES_COLS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : ""))) {
   229	            ps.setLong(1, id);
   230	            try (ResultSet rs = ps.executeQuery()) {
   231	                if (!rs.next()) {
   232	                    throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe.");
   233	                }
   234	                return new Reservation(rs.getLong(1), rs.getInt(2), rs.getString(3), rs.getString(4), rs.getString(5),
   235	                        rs.getDate(6).toLocalDate(), rs.getDate(7).toLocalDate(), rs.getInt(8),
   236	                        RatePlan.valueOf(rs.getString(9)), rs.getInt(10), rs.getBigDecimal(11), rs.getBigDecimal(12),
   237	                        rs.getBigDecimal(13), Status.valueOf(rs.getString(14)), rs.getBigDecimal(15),
   238	                        rs.getBigDecimal(16));
   239	            }
   240	        }
   241	    }
   242	
   243	    private static void update(Connection c, long id, String setClause) throws SQLException {
   244	        try (PreparedStatement ps = c.prepareStatement("UPDATE reservations SET " + setClause + " WHERE id = ?")) {
   245	            ps.setLong(1, id);
   246	            ps.executeUpdate();
   247	        }
   248	    }
   249	
   250	    private static Receipt receipt(Connection c, Reservation r) throws SQLException {
   251	        String type;
   252	        try (PreparedStatement ps = c.prepareStatement("SELECT type FROM rooms WHERE number = ?")) {
   253	            ps.setInt(1, r.roomNumber());
   254	            try (ResultSet rs = ps.executeQuery()) {
   255	                rs.next();
   256	                type = rs.getString(1);
   257	            }
   258	        }
   259	        return new Receipt(r.id(), r.guestName(), r.guestCpf(), r.roomNumber(), type, r.checkIn(), r.checkOut(),
   260	                r.nights(), r.subtotal(), r.discount(), r.total());
