     8	import io.javalin.Javalin;
     9	import io.javalin.http.Context;
    10	
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.time.format.DateTimeParseException;
    14	import java.util.LinkedHashMap;
    15	import java.util.List;
    16	import java.util.Map;
    17	
    18	public class WebApp {
    19	    private static final ObjectMapper MAPPER = new ObjectMapper()
    20	            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
    21	
    22	    private final ReservationService service;
    23	
    24	    public WebApp(ReservationService service) { this.service = service; }
    25	
    26	    public Javalin create() {
    27	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
    28	
    29	        app.get("/rooms", ctx -> json(ctx, 200, service.rooms().stream().map(WebApp::roomJson).toList()));
    30	
    31	        app.post("/reservations", ctx -> json(ctx, 201, reservationJson(service.create(parseNew(ctx.body())))));
    32	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservationJson(service.get(id(ctx)))));
    33	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservationJson(service.confirm(id(ctx)))));
    34	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservationJson(service.cancel(id(ctx)))));
    35	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservationJson(service.checkIn(id(ctx)))));
    36	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, receiptJson(service.checkOut(id(ctx)))));
    37	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, receiptJson(service.document(id(ctx)))));
    38	
    39	        app.get("/messages", ctx -> json(ctx, 200, service.messages().stream().map(WebApp::messageJson).toList()));
    40	
    41	        app.get("/reports/occupancy", ctx -> {
    42	            LocalDate date = parseDate(ctx.queryParam("date"), "date");
    43	            csv(ctx, service.occupancyCsv(date));
    44	        });
    45	        app.get("/reports/revenue", ctx -> {
    46	            String m = ctx.queryParam("month");
    47	            YearMonth month;
    48	            try {
    49	                if (m == null || !m.matches("\\d{4}-\\d{2}")) throw new DateTimeParseException("", "", 0);
    50	                month = YearMonth.parse(m);
    51	            } catch (DateTimeParseException e) {
    52	                throw ApiException.invalid("O parâmetro month deve estar no formato AAAA-MM.");
    53	            }
    54	            csv(ctx, service.revenueCsv(month));
    55	        });
    56	
    57	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    58	        app.exception(Exception.class, (e, ctx) -> {
    59	            e.printStackTrace();
    60	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno.");
    61	        });
    62	        return app;
    63	    }
    64	
    65	    // ---------- entrada ----------
    66	
    67	    private static long id(Context ctx) {
    68	        try {
    69	            return Long.parseLong(ctx.pathParam("id"));
    70	        } catch (NumberFormatException e) {
    71	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + ctx.pathParam("id") + " não existe.");
    72	        }
    73	    }
    74	
    75	    private static LocalDate parseDate(String s, String field) {
    76	        try {
    77	            if (s == null || !s.matches("\\d{4}-\\d{2}-\\d{2}")) throw new DateTimeParseException("", "", 0);
    78	            return LocalDate.parse(s);
    79	        } catch (DateTimeParseException e) {
    80	            throw ApiException.invalid("O campo " + field + " deve ser uma data no formato AAAA-MM-DD.");
    81	        }
    82	    }
    83	
    84	    static NewReservation parseNew(String body) {
    85	        JsonNode root;
    86	        try {
    87	            root = MAPPER.readTree(body);
    88	        } catch (JsonProcessingException e) {
    89	            throw ApiException.invalid("O corpo da requisição não é um JSON válido.");
    90	        }
    91	        if (root == null || !root.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON.");
    92	
    93	        JsonNode room = root.get("roomNumber");
    94	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
    95	            throw ApiException.invalid("roomNumber é obrigatório e deve ser um número inteiro.");
    96	        }
    97	        JsonNode guests = root.get("guests");
    98	        if (guests == null || !guests.isIntegralNumber() || !guests.canConvertToInt()) {
    99	            throw ApiException.invalid("guests é obrigatório e deve ser um número inteiro.");
   100	        }
   101	        String name = text(root, "guestName");
   102	        String email = text(root, "guestEmail");
   103	        String cpf = text(root, "guestCpf");
   104	        LocalDate in = parseDate(text(root, "checkIn"), "checkIn");
   105	        LocalDate out = parseDate(text(root, "checkOut"), "checkOut");
   106	        RatePlan plan;
   107	        try {
   108	            plan = RatePlan.valueOf(text(root, "ratePlan"));
   109	        } catch (IllegalArgumentException e) {
   110	            throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE.");
   111	        }
   112	        if (!out.isAfter(in)) throw ApiException.invalid("A saída deve ser depois da entrada.");
   113	        if (guests.asInt() < 1) throw ApiException.invalid("É preciso pelo menos um hóspede.");
   114	        return new NewReservation(room.asInt(), name, email, cpf, in, out, guests.asInt(), plan);
   115	    }
   116	
   117	    private static String text(JsonNode root, String field) {
   118	        JsonNode n = root.get(field);
   119	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   120	            throw ApiException.invalid(field + " é obrigatório e deve ser um texto.");
   121	        }
   122	        return n.asText().trim();
   123	    }
   124	
   125	    // ---------- saída ----------
   126	
   127	    private static void json(Context ctx, int status, Object body) {
   128	        try {
   129	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
   130	        } catch (JsonProcessingException e) {
   131	            throw new IllegalStateException(e);
   132	        }
   133	    }
   134	
   135	    private static void csv(Context ctx, String body) {
   136	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
   137	    }
   138	
   139	    private static void error(Context ctx, int status, String code, String message) {
   140	        json(ctx, status, Map.of("error", code, "message", message));
   141	    }
   142	
   143	    private static Map<String, Object> roomJson(Room r) {
   144	        Map<String, Object> m = new LinkedHashMap<>();
