    70	            try (PreparedStatement ps = c.prepareStatement(
    71	                    "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    72	                            + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    73	                ps.setInt(1, room.number());
    74	                ps.setDate(2, Date.valueOf(n.checkOut()));
    75	                ps.setDate(3, Date.valueOf(n.checkIn()));
