   159	                ps.setDate(1, Date.valueOf(date));
   160	                ps.setDate(2, Date.valueOf(date));
   161	                try (ResultSet rs = ps.executeQuery()) {
   162	                    while (rs.next()) {
   163	                        occupied++;
   164	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',').append(rs.getLong(3))
   165	                                .append(',').append(rs.getDate(4).toLocalDate()).append(',')
   166	                                .append(rs.getDate(5).toLocalDate()).append('\n');
   167	                    }
   168	                }
   169	            }
   170	            int total;
