   182	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   183	            BigDecimal sum = Pricing.money(BigDecimal.ZERO);
   184	            try (PreparedStatement ps = c.prepareStatement(
   185	                    "SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0) AS amount "
   186	                            + "FROM reservations WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0 "
   187	                            + "ORDER BY check_in, id")) {
   188	                ps.setDate(1, Date.valueOf(month.atDay(1)));
   189	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
   190	                try (ResultSet rs = ps.executeQuery()) {
