   193	                        sum = sum.add(amount);
   194	                        sb.append(rs.getLong(1)).append(',').append(rs.getInt(2)).append(',')
   195	                                .append(rs.getDate(3).toLocalDate()).append(',').append(rs.getDate(4).toLocalDate())
   196	                                .append(',').append(rs.getString(5)).append(',').append(amount.toPlainString()).append('\n');
   197	                    }
   198	                }
