    87	            root = MAPPER.readTree(body);
    88	        } catch (JsonProcessingException e) {
    89	            throw ApiException.invalid("O corpo da requisição não é um JSON válido.");
    90	        }
    91	        if (root == null || !root.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON.");
    92	
    93	        JsonNode room = root.get("roomNumber");
    94	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
    95	            throw ApiException.invalid("roomNumber é obrigatório e deve ser um número inteiro.");
    96	        }
    97	        JsonNode guests = root.get("guests");
    98	        if (guests == null || !guests.isIntegralNumber() || !guests.canConvertToInt()) {
    99	            throw ApiException.invalid("guests é obrigatório e deve ser um número inteiro.");
   100	        }
   101	        String name = text(root, "guestName");
   102	        String email = text(root, "guestEmail");
   103	        String cpf = text(root, "guestCpf");
   104	        LocalDate in = parseDate(text(root, "checkIn"), "checkIn");
   105	        LocalDate out = parseDate(text(root, "checkOut"), "checkOut");
   106	        RatePlan plan;
   107	        try {
   108	            plan = RatePlan.valueOf(text(root, "ratePlan"));
   109	        } catch (IllegalArgumentException e) {
   110	            throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE.");
   111	        }
   112	        if (!out.isAfter(in)) throw ApiException.invalid("A saída deve ser depois da entrada.");
   113	        if (guests.asInt() < 1) throw ApiException.invalid("É preciso pelo menos um hóspede.");
   114	        return new NewReservation(room.asInt(), name, email, cpf, in, out, guests.asInt(), plan);
   115	    }
   116	
   117	    private static String text(JsonNode root, String field) {
   118	        JsonNode n = root.get(field);
   119	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   120	            throw ApiException.invalid(field + " é obrigatório e deve ser um texto.");
   121	        }
   122	        return n.asText().trim();
   123	    }
