   125	    // ---------- saída ----------
   126	
   127	    private static void json(Context ctx, int status, Object body) {
   128	        try {
   129	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
   130	        } catch (JsonProcessingException e) {
   131	            throw new IllegalStateException(e);
   132	        }
   133	    }
   134	
   135	    private static void csv(Context ctx, String body) {
   136	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
   137	    }
