  9	
 10	import java.time.Clock;
 11	import java.time.Instant;
 12	import java.time.LocalTime;
 13	import java.time.ZoneId;
 14	import java.time.ZoneOffset;
 15	import java.util.ArrayList;
 16	import java.util.List;
 17	
 18	import static org.junit.jupiter.api.Assertions.*;
 19	
 20	class MessageDispatcherTest {
 21	    static class MemStore implements MessageDispatcher.Store {
 22	        final List<Message> all = new ArrayList<>();
 23	        final List<String> keys = new ArrayList<>();
 24	
 25	        public Message save(Draft d, MessageStatus s, String key) {
 26	            Message m = new Message(all.size() + 1, d.channel(), d.to(), d.subject(), d.body(), s);
 27	            all.add(m);
 28	            keys.add(key);
 29	            return m;
 30	        }
 31	
 32	        public int countSent(String key, Instant from, Instant to) {
 33	            int n = 0;
 34	            for (int i = 0; i < all.size(); i++) {
 35	                if (key.equals(keys.get(i)) && all.get(i).status() == MessageStatus.SENT) n++;
 36	            }
 37	            return n;
 38	        }
 39	    }
 40	
 41	    private static final ZoneId UTC = ZoneOffset.UTC;
 42	    private static Clock at(String instant) { return Clock.fixed(Instant.parse(instant), UTC); }
 43	    private static final Draft MSG = new Draft("EMAIL", "ana@gmail.com", "Assunto", "Corpo");
 44	
 45	    private static Config cfg(boolean test, Scope archive, QuietHours qh, Scope qs, Integer limit, Scope ls) {
 46	        return new Config(test, archive, qh, qs, limit, ls, UTC);
 47	    }
 48	
 49	    @Test
 50	    void validAddresses() {
 51	        assertTrue(MessageDispatcher.isValidAddress("ana@gmail.com"));
 52	        assertTrue(MessageDispatcher.isValidAddress("a@b.c.d"));
 53	        for (String bad : new String[]{"ana@gmail", "ana.gmail.com", "@gmail.com", "a@@b.com", "a@b@c.com", "a@.com",
 54	                "a@com.", "a@b .com", "", "a@"}) {
 55	            assertFalse(MessageDispatcher.isValidAddress(bad), bad);
 56	        }
 57	    }
 58	
 59	    @Test
 60	    void normalModeSendsAndArchives() {
 61	        var store = new MemStore();
 62	        var out = new MessageDispatcher(Config.defaults(false), Clock.systemUTC()).dispatch(store, MSG);
 63	        assertEquals(2, out.size());
 64	        assertEquals("ana@gmail.com", out.get(0).to());
 65	        assertEquals("Assunto", out.get(0).subject());
 66	        assertEquals(MessageDispatcher.ARCHIVE_ADDRESS, out.get(1).to());
 67	        assertEquals("[Cópia] Assunto", out.get(1).subject());
 68	        assertEquals("Corpo", out.get(1).body());
 69	        assertEquals(MessageStatus.SENT, out.get(1).status());
 70	    }
 71	
 72	    @Test
 73	    void invalidAddressBlockedWithoutCopy() {
 74	        for (boolean test : new boolean[]{false, true}) {
 75	            var store = new MemStore();
 76	            var out = new MessageDispatcher(Config.defaults(test), Clock.systemUTC())
 77	                    .dispatch(store, new Draft("EMAIL", "ana@gmail", "S", "B"));
 78	            assertEquals(1, out.size());
 79	            assertEquals(MessageStatus.BLOCKED, out.get(0).status());
 80	            assertEquals("ana@gmail", out.get(0).to());
 81	            assertEquals("S", out.get(0).subject());
 82	            assertEquals("B", out.get(0).body());
 83	        }
 84	    }
 85	
 86	    @Test
 87	    void testModeRedirectsAndSkipsArchive() {
 88	        var out = new MessageDispatcher(Config.defaults(true), Clock.systemUTC()).dispatch(new MemStore(), MSG);
 89	        assertEquals(1, out.size());
 90	        assertEquals(MessageDispatcher.TEST_ADDRESS, out.get(0).to());
 91	        assertEquals("[TESTE] Assunto", out.get(0).subject());
 92	        assertEquals("Destinatário original: ana@gmail.com\nCorpo", out.get(0).body());
 93	    }
 94	
 95	    @Test
 96	    void archiveCopyInTestModeIsStillRedirected() {
 97	        var cfg = cfg(true, Scope.ALWAYS, null, Scope.ALWAYS, null, Scope.ALWAYS);
 98	        var out = new MessageDispatcher(cfg, Clock.systemUTC()).dispatch(new MemStore(), MSG);
 99	        assertEquals(2, out.size());
100	        assertTrue(out.stream().allMatch(m -> m.to().equals(MessageDispatcher.TEST_ADDRESS)));
101	    }
102	
103	    @Test
104	    void installationWithoutArchive() {
105	        var cfg = cfg(false, Scope.NEVER, null, Scope.ALWAYS, null, Scope.ALWAYS);
106	        assertEquals(1, new MessageDispatcher(cfg, Clock.systemUTC()).dispatch(new MemStore(), MSG).size());
107	    }
108	
109	    @Test
110	    void quietHoursWrapAroundMidnightAndScope() {
111	        var qh = new QuietHours(LocalTime.of(22, 0), LocalTime.of(7, 0));
112	        var always = cfg(false, Scope.NON_TEST_ONLY, qh, Scope.ALWAYS, null, Scope.ALWAYS);
113	        assertEquals(MessageStatus.BLOCKED,
114	                new MessageDispatcher(always, at("2027-03-10T03:00:00Z")).dispatch(new MemStore(), MSG).get(0).status());
115	        assertEquals(MessageStatus.SENT,
116	                new MessageDispatcher(always, at("2027-03-10T12:00:00Z")).dispatch(new MemStore(), MSG).get(0).status());
117	        var testOnly = cfg(false, Scope.NON_TEST_ONLY, qh, Scope.TEST_ONLY, null, Scope.ALWAYS);
118	        assertEquals(MessageStatus.SENT,
119	                new MessageDispatcher(testOnly, at("2027-03-10T03:00:00Z")).dispatch(new MemStore(), MSG).get(0).status());
120	    }
121	
122	    @Test
123	    void dailyLimitPerGuestCountsOnlyOriginals() {
124	        var cfg = cfg(false, Scope.NON_TEST_ONLY, null, Scope.ALWAYS, 2, Scope.ALWAYS);
125	        var d = new MessageDispatcher(cfg, Clock.systemUTC());
126	        var store = new MemStore();
127	        assertEquals(MessageStatus.SENT, d.dispatch(store, MSG).get(0).status());
128	        assertEquals(MessageStatus.SENT, d.dispatch(store, MSG).get(0).status());
129	        assertEquals(MessageStatus.BLOCKED, d.dispatch(store, MSG).get(0).status());
130	        assertEquals(MessageStatus.SENT,
131	                d.dispatch(store, new Draft("EMAIL", "bia@gmail.com", "S", "B")).get(0).status());
132	    }
133	}
