160	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2028-02-29")));
161	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-03-01")));
162	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-07-31")));
