169	                RatePlan.NON_REFUNDABLE);
170	        assertEquals(new BigDecimal("779.80"), q.subtotal());
171	        assertEquals(new BigDecimal("116.97"), q.discount()); // 116.97 exato
172	        assertEquals(new BigDecimal("662.83"), q.total());
173	    }
174	
175	    @Test
176	    void halfEvenRounding() {
177	        // 249.90 * 0.15 = 37.485 -> meio para o par = 37.48
178	        var q = Pricing.quote(STD, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-11"), RatePlan.NON_REFUNDABLE);
179	        assertEquals(new BigDecimal("37.48"), q.discount());
180	        assertEquals(new BigDecimal("212.42"), q.total());
181	    }
