184	    void receiptText() {
185	        var r = new Receipt(7, "Carla Dias", "11122233344", 201, "DELUXE", LocalDate.parse("2027-03-10"),
186	                LocalDate.parse("2027-03-12"), 2, new BigDecimal("1779.80"), new BigDecimal("0.00"), new BigDecimal("1779.80"));
187	        assertEquals("""
188	                Comprovante de reserva nº 7
189	                Hóspede: Carla Dias (CPF 111.222.333-44)
190	                Quarto: 201 (DELUXE)
191	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
192	                Diárias: R$ 1.779,80
193	                Total: R$ 1.779,80""", r.text());
194	    }
