 81	    Resp call(String method, String path, String body) throws Exception {
 82	        var b = HttpRequest.newBuilder(URI.create(base + path));
 83	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 84	        var r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 85	        return new Resp(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
 86	    }
