 88	    static String body(int room, String in, String out, int guests, String plan, String email) {
 89	        return """
 90	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"%s","guestCpf":"111.222.333-44",
 91	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, email, in, out, guests, plan);
 92	    }
 93	
 94	    JsonNode create(int room, String in, String out, int guests, String plan, String email) throws Exception {
 95	        Resp r = call("POST", "/reservations", body(room, in, out, guests, plan, email));
 96	        assertEquals(201, r.status(), r.body());
 97	        return r.json();
 98	    }
