185	    @Test
186	    void validationAndErrors() throws Exception {
187	        assertEquals(400, call("POST", "/reservations", "não é json").status());
188	        assertEquals(400, call("POST", "/reservations", "[]").status());
189	        assertEquals(400, call("POST", "/reservations", "{}").status());
190	        assertEquals(400, call("POST", "/reservations", body(101, "2027-03-10", "2027-03-10", 1, "STANDARD", "a@b.com")).status());
191	        assertEquals(400, call("POST", "/reservations", body(101, "2027-03-10", "2027-03-09", 1, "STANDARD", "a@b.com")).status());
192	        assertEquals(400, call("POST", "/reservations", body(101, "2027-03-10", "2027-03-11", 0, "STANDARD", "a@b.com")).status());
193	        assertEquals(400, call("POST", "/reservations", body(101, "10/03/2027", "2027-03-11", 1, "STANDARD", "a@b.com")).status());
194	        assertEquals(400, call("POST", "/reservations", body(101, "2027-03-10", "2027-03-11", 1, "VIP", "a@b.com")).status());
195	        Resp nf = call("POST", "/reservations", body(999, "2027-03-10", "2027-03-11", 1, "STANDARD", "a@b.com"));
196	        assertEquals(404, nf.status());
197	        assertEquals("ROOM_NOT_FOUND", nf.json().get("error").asText());
