202	        assertEquals(404, call("POST", "/reservations/42/confirmation", null).status());
203	        assertEquals(400, call("GET", "/reports/occupancy?date=10-07-2027", null).status());
204	        assertEquals(400, call("GET", "/reports/occupancy", null).status());
205	        assertEquals(400, call("GET", "/reports/revenue?month=2027-13", null).status());
206	        assertEquals(400, call("GET", "/reports/revenue?month=2027-7", null).status());
