248	        assertEquals("reservation,room,check_in,check_out,status,amount\n"
249	                + "2,101,2027-07-09,2027-07-10,CONFIRMED,299.88\n"
250	                + "1,301,2027-07-10,2027-07-12,CONFIRMED,1391.76\n"
